<?php
declare(strict_types=1);$root=dirname(__DIR__);$signup=file_get_contents($root.'/app/Controllers/CommercialController.php');$checkout=file_get_contents($root.'/app/Services/CheckoutService.php');$webhook=file_get_contents($root.'/app/Controllers/WebhookController.php');$fail=[];foreach(['beginTransaction','trial_without_card=1','password_hash','terms_acceptances']as$n)if(!str_contains($signup,$n))$fail[]='signup:'.$n;foreach(['monthly_price','coupons','subtotal']as$n)if(!str_contains($checkout,$n))$fail[]='checkout:'.$n;foreach(['hash_hmac','event_id','FOR UPDATE','idempotency_key']as$n)if(!str_contains($webhook,$n))$fail[]='webhook:'.$n;if($fail){fwrite(STDERR,implode("\n",$fail));exit(1);}echo "OK: signup atômico, preço server-side e webhook idempotente presentes.\n";
